#include <iostream>
using namespace std;

int a[20010];
int keys[11];

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; ++i)
        cin >> a[i];
    for (int i = 0; i < 10; ++i)
        cin >> keys[i];
    for (int i = 0; i < n; ++i)
        cout << keys[a[i]] << ' ';
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

char s[1010];

int main() {
    int n;
    cin >> n;
    cin >> s;
    for (int i = 0; i < n; ++i) {
        char c = s[i];
        if ('a' <= c && c <= 'z')
            cout << (char)(c - ('a' - 'A'));
        else if ('A' <= c && c <= 'Z')
            cout << (char)(c + ('a' - 'A'));
        else
            cout << '*';
    }
    cout << endl;
    return 0;
}
